"""Recover atomically committed worker outputs after a process restart."""
import re
import stat


def completed_output(directory, job_id, extension):
    # Only IDs generated by the workers may select a file. Never follow links.
    if not isinstance(job_id, str) or not re.fullmatch(r'[a-f0-9]{32}', job_id):
        return None
    path = directory / f'{job_id}.{extension}'
    try:
        info = path.lstat()
        if not stat.S_ISREG(info.st_mode) or info.st_size == 0:
            return None
    except OSError:
        return None
    return path


def recovered_job(directory, job_id, extension, message):
    if completed_output(directory, job_id, extension) is None:
        return None
    return {'id': job_id, 'status': 'completed', 'message': message, 'recovered': True}
